const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
box.show();

function show() {
  console.log(this.n);
}
const a = { n: 1, show };
const b = { n: 2, show };
a.show();
b.show();

'use strict';
const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
function run(fn) {
  try {
    fn();
  } catch {
    console.log(2);
  }
}
run(box.show);
run(() => box.show());

function show() {
  console.log(this.n);
}
show.call({ n: 1 });
show.call({ n: 2 });

const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
const show = box.show.bind({ n: 2 });
show();
box.show();

const box = {
  n: 1,
  show() {
    const inner = {
      n: 2,
      read: () => console.log(this.n),
    };
    inner.read();
  },
};
box.show();

const box = {
  n: 1,
  show() {
    const self = this;
    function inner() {
      console.log(self.n);
      console.log(this.n);
    }
    inner.call({ n: 2 });
  },
};
box.show();

function Box(n) {
  this.n = n;
}
console.log(new Box(1).n);
console.log(new Box(2).n);

const box = {
  n: 1,
  step() {
    this.n += 1;
  },
  run() {
    this.step();
    console.log(this.n);
  },
};
box.run();

const box = {
  n: 1,
  show() {
    console.log(this.n);
  },
};
box['show']();
const name = 'show';
box[name]();

const box = {
  n: 1,
  show() {
    setTimeout(() => console.log(this.n), 0);
  },
};
box.show();

function Box(n) {
  this.n = n;
  this.read = function () {
    console.log(this.n);
  };
}
const box = new Box(1);
box.read();
box.read.call({ n: 2 });

const box = {
  n: 1,
  add() {
    this.n += 1;
    return this;
  },
};
box.add().add();
console.log(box.n);

'use strict';
const box = {
  n: 1,
  add() {
    this.n += 1;
    return this;
  },
};
const add = box.add;
try {
  add();
} catch {
  console.log(box.n);
}
box.add();
console.log(box.n);

const outer = {
  n: 1,
  make() {
    return {
      n: 2,
      show() {
        console.log(this.n);
      },
    };
  },
};
outer.make().show();

function log(obj) {
  console.log(obj.n);
}
const box = {
  n: 1,
  show() {
    log(this);
  },
};
box.show();
const show = box.show;
show.call({ n: 2 });
